import {ATTENTION_INTRO} from './audio-cast.mjs';
import {messages} from './data.mjs';

export const CHARACTER_CELLS={B:[0,0],C:[1,0],D:[2,0],E:[0,1],F:[1,1],guide:[2,1]};
export const PHONE_ALERTS=[
 {from:'Sam',person:'B',app:'Messages',text:'Have you seen the photo in the group chat?',reply:'I was going to show you what I found on my walk. You can look when you’re finished.'},
 {from:'Jo',person:'C',app:'Messages',text:'Are we still meeting later?',reply:'I’m making a plan for this afternoon. There’s no need to answer during your search.'},
 {from:'Photo club',person:'F',app:'Photos',text:'A new photo has been added to the album.',reply:'The courtyard looks different in the afternoon light. Your notes will still be there when you go back.'},
 {from:'Lee',person:'E',app:'Messages',text:'I have a question for you…',reply:'I was wondering which book you chose. Let’s talk after you’ve finished what you’re doing.'}
];
export function html(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function glyph(name){
 const paths={message:'<path d="M5 5h14v11H9l-4 4V5Z"/><path d="M8 9h8M8 12h5"/>',notes:'<path d="M6 3h12v18H6zM9 7h6M9 11h6M9 15h4"/>',photo:'<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m4 18 6-6 4 4 3-3 3 4"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',play:'<path d="m9 5 10 7-10 7V5Z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',sound:'<path d="m11 5-5 4H3v6h3l5 4V5Zm4 3c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',bell:'<path d="M5 17h14l-2-3v-4a5 5 0 0 0-10 0v4l-2 3Zm5 4h4"/>',home:'<path d="m3 11 9-8 9 8M6 10v11h12V10M10 21v-7h4v7"/>',arrow:'<path d="m14 5-7 7 7 7"/>',notice:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>',check:'<path d="m5 12 4 4L19 6"/>',phone:'<path d="M8 3H5a2 2 0 0 0-2 2c0 9 7 16 16 16a2 2 0 0 0 2-2v-3l-5-2-2 3c-4-2-5-3-7-7l3-2-2-5Z"/>'};
 return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.message}</svg>`;
}
export function portrait(id,extra=''){
 if(id==='A')return `<span class="paper-avatar ${extra}" aria-hidden="true">${glyph('notice')}</span>`;
 const [x,y]=CHARACTER_CELLS[id]||CHARACTER_CELLS.guide;
 return `<span class="painted-person ${extra}" style="--person-x:${x*50}%;--person-y:${y*100}%" aria-hidden="true"></span>`;
}
export function listenButton(key,label){return `<button type="button" class="listen-button" data-listen="${key}" aria-label="${html(label)}">${glyph('play')}<span>${label}</span></button>`;}
export function phoneFrame(body,{label='Practice phone',className='',bar='9:41'}={}){return `<div class="practice-phone ${className}" role="region" aria-label="${html(label)}"><div class="phone-island" aria-hidden="true"></div><div class="phone-status" aria-hidden="true"><span>${bar}</span><span class="status-symbols">▂▄▆ <span class="battery-icon"></span></span></div>${body}<div class="phone-home-indicator" aria-hidden="true"></div></div>`;}
export function appHeader(title,subtitle='',back=false){return `<div class="phone-app-heading">${back?`<button class="phone-back" type="button" data-sandbox-app="home" aria-label="Return to the phone home screen">${glyph('arrow')}</button>`:''}<div><strong>${title}</strong>${subtitle?`<span>${subtitle}</span>`:''}</div></div>`;}
export function sandboxPhone(app='home',notification=false,sound=false){
 let body='';
 if(app==='home')body=`<div class="phone-wallpaper"><p class="phone-day">A little time to explore</p><p class="phone-clock">9:41</p><p class="phone-hint">Open an app and have a look around.</p><div class="phone-app-grid">${[['messages','Messages','message'],['notes','Notes','notes'],['photos','Photos','photo'],['settings','Settings','settings']].map(([key,name,icon])=>`<button type="button" class="app-tile ${key}" data-sandbox-app="${key}" aria-label="Open ${name} on the practice phone"><span>${glyph(icon)}</span>${name}</button>`).join('')}</div><div class="phone-dock">${glyph('phone')}${glyph('message')}${glyph('photo')}</div></div>`;
 if(app==='messages')body=`${appHeader('Messages','Your practice conversations',true)}<div class="phone-scroll"><div class="chat-person">${portrait('B','small-person')}<div><strong>Sam</strong><span>A message for you</span></div></div><div class="chat-bubble incoming">Have you seen the photo in the group chat?</div><div class="chat-bubble incoming">I was going to show you what I found on my walk. You can look when you’re finished.</div><p class="chat-aside">A preview can leave you wondering what comes next, even before you open the conversation.</p><button type="button" class="phone-return" data-sandbox-app="notes">Return to your notes ${glyph('notes')}</button></div>`;
 if(app==='notes')body=`${appHeader('Notes','A place to keep your task',true)}<div class="phone-scroll notebook-screen"><p class="notes-date">My notes</p><h3>Where was I?</h3><p>When you leave one thing to check another, you may need to find your place before continuing.</p><p>In the next activity, this Notes app will hold the letter search. Messages will appear while you are working in the interrupted round.</p><button type="button" class="in-phone-action" data-demo-notification>Try a notification</button></div>`;
 if(app==='photos')body=`${appHeader('Photos','A glimpse of Alder Library',true)}<div class="phone-scroll"><img class="phone-photo" src="assets/alder-library.png" alt="Watercolor illustration of a library courtyard"><p class="phone-photo-caption">The courtyard in the afternoon.</p><p class="chat-aside">The Photos app gives you something else to look at. When you’re ready, return to Notes and notice whether you have to find your place again.</p><button type="button" class="phone-return" data-sandbox-app="notes">Return to your notes ${glyph('notes')}</button></div>`;
 if(app==='settings')body=`${appHeader('Settings','Choose how this phone sounds',true)}<div class="phone-scroll"><div class="settings-row"><span>${glyph('sound')} Gentle notification sound</span><button type="button" class="phone-switch ${sound?'on':''}" id="sandbox-sound" role="switch" aria-checked="${sound}" aria-label="Gentle notification sound">${sound?'On':'Off'}</button></div><p class="chat-aside">Sound starts off. If you turn it on, the phone will make a soft chime when a notification arrives. Your choice will also be kept with a new search round.</p><p class="chat-aside">You can read every message without sound. Nothing here sends a message or opens a real account.</p></div>`;
 return phoneFrame(`${body}${notification?`<button type="button" class="phone-notification demo-banner" data-sandbox-app="messages"><span class="notification-app-icon">${glyph('message')}</span><span><span class="notification-meta">MESSAGES <small>now</small></span><strong>Sam</strong><span>Have you seen the photo in the group chat?</span></span></button>`:''}`,{label:'Explore the practice phone',className:'sandbox-device'});
}
export function introScene(slug,st){
 if(slug==='attention')return `<section class="illustrated-world desk-world intro-world" aria-label="An illustrated desk with an interactive practice phone"><div class="world-light"></div><aside class="world-guide">${portrait('guide','guide-person')}<div class="guide-speech"><p class="eyebrow">Before we begin</p><p class="coach-copy">${ATTENTION_INTRO}</p>${listenButton('guide-attention','Listen to the introduction')}</div></aside><div class="world-device" id="sandbox-device">${sandboxPhone(st.sandboxApp||'home',st.demoNotification,!!st.phoneSound)}</div><div class="world-caption">Your desk · a phone, a task, and a few things competing for attention</div></section>`;
 return `<section class="illustrated-world library-world intro-world" aria-label="The Alder Library courtyard and an illustrated caller"><div class="world-light"></div><aside class="world-guide">${portrait('B','guide-person')}<div class="guide-speech"><p class="eyebrow">A message from Sam</p><p class="coach-copy">Sam has something to tell you about Saturday’s star viewing. Listen to his message or read it on the phone. Later, you’ll follow the conversation to see how the information changes.</p></div></aside><div class="world-device">${phoneFrame(`${appHeader('Alder Library','A conversation to investigate')}<div class="call-screen"><div class="call-person">${portrait('B','caller-person')}<span class="voice-waves" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span></div><h3>Sam</h3><p class="call-subtitle">A voice message for you</p>${listenButton('message-B','Listen to Sam')}<p class="audio-status" data-audio-status role="status">You can listen or read the message below.</p><div class="chat-bubble incoming">${messages[1].text}</div></div>`,{label:'Sam’s message on the practice phone'})}</div><div class="world-caption">Alder Library · follow what people say, then look back at where it came from</div></section>`;
}
export function conversationScene(st){
 const m=messages.find(x=>x.id===st.selected)||messages[1],parent=messages.find(x=>x.id===m.parent);
 const contacts=messages.slice(1).map(x=>`<button type="button" class="character-contact ${m.id===x.id?'selected':''} ${st.visited.includes(x.id)?'explored':''}" data-node="${x.id}" aria-label="Read message ${x.id}, ${x.sender}" aria-pressed="${m.id===x.id}">${portrait(x.id,'contact-person')}<span>${x.sender}<small>Message ${x.id}</small></span>${st.visited.includes(x.id)?'<span class="contact-tick" aria-hidden="true">✓</span>':''}</button>`).join('');
 return `<section class="illustrated-world library-world conversation-world" aria-label="Investigate the Alder Library conversation"><div class="world-light"></div><div class="conversation-contacts"><h2>Who passed it along?</h2><p>Choose someone to open their message.</p>${contacts}<button type="button" class="notice-shortcut" data-node="A">${glyph('notice')} Read the library notice</button></div><div class="conversation-device">${phoneFrame(`${appHeader('Saturday’s star viewing','Alder Library conversation')}<div class="call-screen">${m.id==='A'?`<div class="call-person">${portrait('A','caller-person')}</div><h3>Library notice</h3><p class="call-subtitle">Thursday · 10 a.m.</p>`:`<div class="call-person" data-caller="${m.id}">${portrait(m.id,'caller-person')}<span class="voice-waves" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span></div><h3>${m.sender}</h3><p class="call-subtitle">Message ${m.id} · ${m.time}</p>`}${listenButton('message-'+m.id,m.id==='A'?'Read the notice aloud':'Listen to '+m.sender)}<p class="audio-status" data-audio-status role="status">The message is written here too.</p><div class="chat-bubble incoming">${html(m.text)}</div>${parent?`<button type="button" class="heard-from" data-node="${parent.id}">${glyph('arrow')} ${m.sender} ${parent.id==='A'?'read the library notice':'heard '+parent.sender+'’s message'} <span>${parent.id}</span></button>`:'<p class="chat-aside">The library notice is the starting record in this route.</p>'}</div>`,{label:m.sender+'’s message',className:'conversation-phone',bar:m.time.replace('Thursday · ','').replace(' a.m.','')})}</div><aside class="conversation-insight"><div class="pinned-note"><span class="paper-pin" aria-hidden="true"></span><p class="eyebrow">Look at what changed</p><h3>${m.id==='A'?'The starting notice':m.sender+'’s version'}</h3><p>${m.note}</p>${parent?`<details class="earlier-message"><summary>Read the message ${m.sender} received</summary><p class="small"><strong>${parent.sender} · ${parent.id}</strong></p><p>${parent.text}</p></details>`:''}</div></aside></section>`;
}
export function taskNotification(alert,number){return `<div class="notification-envelope"><button type="button" class="phone-notification task-banner" id="open-notification"><span class="notification-app-icon">${glyph(alert.app==='Photos'?'photo':'message')}</span><span><span class="notification-meta">${alert.app.toUpperCase()} <small>now · ${number}</small></span><strong>${alert.from}</strong><span>${alert.text}</span></span></button><button type="button" id="dismiss-notification" class="dismiss-notification" aria-label="Dismiss this notification and keep working">×</button></div>`;}
export function notificationConversation(alert){return `<div class="notification-thread"><button type="button" class="phone-return" id="back-to-notes">${glyph('arrow')} Back to Notes</button><div class="chat-person">${portrait(alert.person,'small-person')}<div><strong>${alert.from}</strong><span>${alert.app}</span></div></div><div class="chat-bubble incoming">${alert.text}</div><div class="chat-bubble incoming">${alert.reply}</div><p class="chat-aside">Your search is still in Notes, and the clock is still running. Return when you’re ready to continue.</p><button type="button" class="in-phone-action" id="return-to-search">Return to my search</button></div>`;}
